	"eam/ui/view/fragment/EmployeeDialog.fragment.xml":'<core:FragmentDefinition\n    xmlns="sap.m"\n    xmlns:core="sap.ui.core"><Dialog\n        title="{employee>/title}"\n        contentWidth="440px"\n        stretchOnPhone="true"\n        class="eamDialog"><content><VBox class="sapUiSmallMargin eamDialogContent"><items><Label text="First name" required="true"/><Input\n                        value="{employee>/FirstName}"\n                        maxLength="50"\n                        valueState="{employee>/state/FirstName}"\n                        valueStateText="First name is required"\n                        liveChange=".onFieldChange"/><Label text="Last name" required="true"/><Input\n                        value="{employee>/LastName}"\n                        maxLength="50"\n                        valueState="{employee>/state/LastName}"\n                        valueStateText="Last name is required"\n                        liveChange=".onFieldChange"/><Label text="Email" required="true"/><Input\n                        type="Email"\n                        value="{employee>/Email}"\n                        maxLength="100"\n                        valueState="{employee>/state/Email}"\n                        valueStateText="Enter a valid email address"\n                        liveChange=".onFieldChange"/><Label text="Department"/><Input\n                        value="{employee>/Department}"\n                        maxLength="100"/></items></VBox></content><beginButton><Button text="{employee>/confirmText}" type="Emphasized" press=".onSaveEmployee"/></beginButton><endButton><Button text="Cancel" press=".onCancelEmployee"/></endButton></Dialog></core:FragmentDefinition>'
